require "application_system_test_case"

class LayoutCheckTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  test "inspect layout metrics" do
    card = cards(:logo)
    comment = comments(:logo_agreement_jz)
    r_text = comment.reactions.create!(content: "Nice work!", reacter: users(:david))
    r_emoji = comment.reactions.create!(content: "🔥", reacter: users(:kevin))

    sign_in_as(users(:david))
    visit card_url(card)

    metrics = evaluate_script(<<~JS)
      (() => {
        const rect = (sel) => {
          const el = document.querySelector(sel)
          if (!el) return null
          const r = el.getBoundingClientRect()
          const s = getComputedStyle(el)
          return { w: Math.round(r.width), h: Math.round(r.height), display: s.display, cursor: s.cursor, fontSize: s.fontSize, naturalW: el.naturalWidth }
        }
        return {
          comment: rect("##{dom_id(comment)}"),
          reactions: rect("##{dom_id(comment)} .reactions"),
